//! Fixed, untagged original TryCatch parameter-count Warning.
use super::*;
struct Catch<'a,'w,W>{archive:&'a BodyArchive,work:&'w mut W,rows:Vec<Row>}
impl<W:EffectReportWork> crate::checker_expression_visit::CatchObserver<PolicyFailure> for Catch<'_,'_,W>{fn parameters(&mut self,count:usize,at:Span,expression:Span)->Result<(),PolicyFailure>{if count<=1{return Ok(())}let message=text(self.work,format_args!("Expected 0 or 1 catch parameters, got {count}"))?;push(self.work,&mut self.rows,Row{diagnostic:Diagnostic{family:"catch_parameter_count",severity:Severity::Warning,span:at,expression_span:expression,message,notes:Vec::new()},synthetic:false})}}
pub fn with_archived_body<W:EffectReportWork,R:Resolver+?Sized>(archive:&BodyArchive,body:&ArchivedBody<'_>,resolver:&R,profile:PackedU128,work:&mut W,checkpoint:&dyn Fn()->io::Result<()>,consume:impl FnOnce(&Findings<'_>)->Result<(),PolicyFailure>)->Result<(),PolicyFailure>{checkpoint().map_err(PolicyFailure::Operational)?;if !body.belongs_to(archive)||resolver.source_owner()!=Some(std::ptr::from_ref(archive.tree()).cast()){return Err("catch policy belongs to another actual archive/body/resolver".into())}archive.tree().validate_checker_builtin_profile(profile).map_err(|error|format!("catch actual profile: {error:?}"))?;let mut observer=Catch{archive,work,rows:Vec::new()};let pending=(||{crate::checker_expression_visit::catch_parameters_archived(archive,body,resolver,profile,checkpoint,&mut observer)?;let findings=Findings::from_rows(observer.archive,std::mem::take(&mut observer.rows));checkpoint().map_err(PolicyFailure::Operational)?;consume(&findings)})();if matches!(&pending,Err(PolicyFailure::Operational(_))){return pending}checkpoint().map_err(PolicyFailure::Operational)?;pending}
